-- =====================================================================
-- Niks Masala — Supabase product seed (40 rows)
--
-- Why this exists
--   /functions/api/order/create.js looks up canonical prices in the
--   `products` table when an order is placed. If the table is empty, every
--   checkout fails with "Unknown product pX". This file backfills the same
--   catalog that assets/app.js ships to the browser as DEFAULT_PRODUCTS.
--
-- How to run
--   1. Open Supabase → SQL Editor → New query.
--   2. Paste this entire file.
--   3. Run. Safe to re-run — idempotent via ON CONFLICT (id) DO UPDATE.
--
-- After it runs
--   - Place a test order. The "Unknown product" toast disappears.
--   - To change a price / add a variant, edit assets/app.js, then re-run
--     this file (or update the row directly in Supabase).
-- =====================================================================

ON CONFLICT (id) DO UPDATE SET
  name        = EXCLUDED.name,
  slug        = EXCLUDED.slug,
  category    = EXCLUDED.category,
  price       = EXCLUDED.price,
  weight      = EXCLUDED.weight,
  image       = EXCLUDED.image,
  variants    = EXCLUDED.variants,
  description = EXCLUDED.description,
  long_desc   = EXCLUDED.long_desc,
  badge       = EXCLUDED.badge,
  stock       = EXCLUDED.stock;

-- Sanity check after running:
--   SELECT count(*) FROM products;        -- expect 40
--   SELECT id, name, price FROM products ORDER BY id LIMIT 5;
